"""Readable validated progress, bounded public scope and explicit performance limitations."""
def render_report(source,speakers,assertions,revision,benchmark,jar,baseline,fingerprint,focused):
 n=lambda x:f'{x:,}'.replace(',',' ')
 out=['# Большая партия NPC — 0.15.93','','`█████████████████░░░░░░░░░░░░░` **57,10%** точных ключей зафиксированной публичной базы; полоса округлена.','','| Учёт | До | После |','| --- | ---: | ---: |','| Точные ключи | 8 735 · 53,77% | 9 276 · 57,10% |','| Без подтверждённого точного ключа | 7 509 | 6 968 · 42,90% |','| Всего строк в базе | 16 244 | 16 244 |','','Это не процент полностью готовой игры. Закрытые серверные скрипты недоступны; публичная очередь включает исторические, нейтральные, структурные и редакторские строки. Динамический перевод может работать и без точного ключа.','','| Говорящий | Новых реплик |','| --- | ---: |']
 out += [f'| {s} | {c} |' for s,c in speakers.items()]
 out += ['| Всего | 541 |','','Отбор: 638 строк, 320 полных блоков, 46 страниц. 541 новый ключ, 52 прежних, 40 структурных и 5 нейтральных строк. Математический интеграл не переводится; извлечённое имя Player оставлено структурной переменной. 60 точных общих пар переиспользованы из вычитанной партии 92 с отдельной атрибуцией.','','11 новых упорядоченных групп / 12 переведённых подписей / 11 опубликованных оформлений. Шесть строк, содержащих только заголовок многострочного меню, не засчитаны готовыми группами. Кнопки без Select-заголовка не объявлены исправленными.','','## Качество и ограничения','','[Контекстная вычитка всех выбранных веток](NPC_0.15.93_REVIEW_NOTES.md).',f'На одном окончательном JAR пройдена 161 свежая группа проверок и 15 тестов извлечения. Новая партия: {n(assertions["TestNpc93"])} проверок реплик и {n(assertions["TestNpcChoices93"])} проверок ответов. Проверены все 542 опубликованных оформления новых реплик, фрагментация, цвета, актуальные команды/подсказки, числа, счётчики, переключатели, пользовательские переопределения и защита подписанного/пользовательского чата.',f'Публичный API: {revision["checked_at"]}. Из 46 страниц 43 совпали с зафиксированными редакциями. У Mage Guard и Barbarian Guard изменён только внешний раздел Behavior, у Spaceman — ссылка места появления. Полные пары редакций и точные различия сохранены; все разделы Dialogue вместе с условиями совпали. Замороженная очередь не переписывалась.','','У Серафины 13 новых ключей относятся к историческим этапам сопротивления/Данте, выборов и строительства центра: они не названы действующими ветками. Некоторые условия Spaceman помечены в источнике ahn. Новые реплики Мэддокса относятся к Разлому. У Керана сохранена спорная атрибуция одной реплики со страницы Prie. Всё это явно отражено в источниках, а не скрыто в общем проценте.','','Числа из обучения холоду сохранены как опубликовано, даже при кажущемся противоречии между примером и формулой. Единственное лексическое исключение: 2 в `im goin 2 da circus` означает to, поэтому перевод «еду в цирк», а не количество два. Остальные числовые значения сохраняются.','','| Те же 11 247 строк: срабатывание, не оценка качества | 92 | 93 |','| --- | ---: | ---: |','| Обычный текст | 8 696 | 9 237 |','| Опубликованные цвета | 8 624 | 9 165 |','','Все 541 новых ключа сработали в обоих режимах; вне них результаты не изменились. У Хины и Космонавта дополнительно исправлены точные привязки цветной пунктуации. 72 прежних цветных кандидата остаются открытыми.','','## Нагрузка','','Изменены только регистрация ресурса при запуске и точная таблица ответов. Новых регулярных выражений, сетевого перевода, провайдеров или покадровых обходов нет. Вся остальная логика сопоставления и все классы HUD/F3 сохранены. Четыре внутренних класса проверены на равенство исполняемого кода; прежние ресурсы не менялись.',f'Рост JAR: {n(jar.stat().st_size-baseline.stat().st_size)} байт. Полная база исходников в мод не включена.','','Четыре отдельные JVM: 92 → 93 → 93 → 92. 33 сценария: 31 прежний с одинаковой полезной работой и 2 новых с дополнительным переводом. По 200 000 прогревочных вызовов и четыре раунда не менее 40 000 измеряемых вызовов на сценарий.','','| Сценарий | Мкс/сообщение до → после, два порядка | Изменение | Байт/сообщение до → после |','| --- | ---: | ---: | ---: |']
 for r in benchmark['summary']:
  times=' / '.join(f'{o["before_ns"]/1000:.2f} → {o["after_ns"]/1000:.2f}' for o in r['orders']);change=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);allocation=' / '.join(f'{o["before_bytes"]:.0f} → {o["after_bytes"]:.0f}' for o in r['orders']);out.append(f'| {r["mode"]} | {times} | {change} | {allocation} |')
 values=[o['wall_change_percent'] for r in benchmark['summary'] if r['equal_useful_output'] for o in r['orders']]
 out += ['',f'В первом полном сравнении одинаковой работы разброс составил {min(values):+.1f}%…{max(values):+.1f}%. Сценарий existing_choices84 оказался медленнее в обоих порядках, поэтому выполнен дополнительный целевой повтор, а не выбран только удобный результат. Шесть сценариев, ещё четыре JVM в порядке 92 → 93 → 93 → 92, по 300 000 прогревочных и четыре раунда не менее 200 000 измеряемых вызовов.','','| Повтор | Мкс/сообщение до → после, два порядка | Изменение |','| --- | ---: | ---: |']
 for r in focused['summary']:
  times=' / '.join(f'{o["before_ns"]/1000:.2f} → {o["after_ns"]/1000:.2f}' for o in r['orders']);change=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);out.append(f'| {r["mode"]} | {times} | {change} |')
 choice=next(r for r in focused['summary'] if r['mode']=='existing_choices84');styled=next(r for r in focused['summary'] if r['mode']=='existing_style')
 out += ['',f'Для первоначально подозрительного existing_choices84 повтор дал {choice["orders"][0]["wall_change_percent"]:+.1f}% / {choice["orders"][1]["wall_change_percent"]:+.1f}% — прежнее замедление не воспроизвелось. В existing_style осталось увеличение на '+ ' / '.join(f'{(o["after_ns"]-o["before_ns"])/1000:.2f} мкс/сообщение' for o in styled['orders'])+'; оно не скрыто и не выдано за нулевую нагрузку.','','Первичный разброс не скрыт и не заменён повтором: исходные данные обоих опытов и реально исполнявшиеся классы измерителя сохранены. Результаты относятся к обработке сообщений, не к FPS игры. Повтор не сертификат отсутствия микролагов.']
 out += ['',f'В 31 прежнем сценарии: от {min(values):+.1f}% до {max(values):+.1f}% в этих запусках. Это измерения обработки входящего чата, не доказательство ускорения или отсутствия микролагов. Два new_* сценария выполняют разную полезную работу до/после; их проценты нельзя выдавать за ускорение того же перевода. Все раунды сохранены в BENCHMARK_RAW.json.','','FPS, 0,1% lows, GPU и время кадра в игре здесь не измерялись. Нулевая нагрузка не обещана. JAR автоматически не устанавливался, Minecraft не перезапускался.','','## Что осталось','','6 968 строк без подтверждённого точного ключа. Остаются переменные, многострочные меню, ошибки публикации/извлечения, 72 старых цветных кандидата и прежние открытые проверки ReviewedLoreStyles/Bingo. Ни весь NPC-реестр, ни весь Абифон, ни вся игра не объявляются готовыми.','','[Все говорящие и остаток](NPC_ALL_SPEAKERS_0.15.93_RU.md).','',f'SHA-256 JAR: `{fingerprint}`.']
 (source/'NPC_PROGRESS_0.15.93_RU.md').write_text('\n'.join(out)+'\n',encoding='utf-8')
